import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ParserBase.resetFloat.
 * Since ParserBase is an abstract class and the method is protected, 
 * we use a concrete subclass for testing.
 */
public class ParserBase_resetFloat_TriageGen1Test {

    private TestParser parser;

    // Concrete implementation of the abstract ParserBase for testing purposes
    private static class TestParser extends ParserBase {
        protected TestParser(IOContext ctxt, int features) {
            super(ctxt, features);
        }

        @Override
        protected void _closeInput() {}

        @Override
        protected void _releaseBuffers() {}

        @Override
        protected void _handleEOF() {}

        // Expose the protected method for testing
        public JsonToken callResetFloat(boolean negative, int intLen, int fractLen, int expLen) {
            return resetFloat(negative, intLen, fractLen, expLen);
        }

        // Accessors to verify internal state via reflection if necessary, 
        // but here we will use reflection to check the fields directly.
    }

    @Before
    public void setUp() {
        parser = new TestParser(new IOContext(), 0);
    }

    @Test
    public void testResetFloat_PositiveValues() throws Exception {
        boolean negative = false;
        int intLen = 5;
        int fractLen = 3;
        int expLen = 2;

        JsonToken token = parser.callResetFloat(negative, intLen, fractLen, expLen);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals(negative, getInternalField("_numberNegative"));
        assertEquals(intLen, getInternalField("_intLength"));
        assertEquals(fractLen, getInternalField("_fractLength"));
        assertEquals(expLen, getInternalField("_expLength"));
        // NR_UNKNOWN is typically 0 in Jackson internals for uninitialized types
        assertEquals(0, getInternalField("_numTypesValid"));
    }

    @Test
    public void testResetFloat_NegativeValues() throws Exception {
        boolean negative = true;
        int intLen = 10;
        int fractLen = 10;
        int expLen = 10;

        JsonToken token = parser.callResetFloat(negative, intLen, fractLen, expLen);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals(negative, getInternalField("_numberNegative"));
        assertEquals(intLen, getInternalField("_intLength"));
        assertEquals(fractLen, getInternalField("_fractLength"));
        assertEquals(expLen, getInternalField("_expLength"));
        assertEquals(0, getInternalField("_numTypesValid"));
    }

    @Test
    public void testResetFloat_ZeroLengths() throws Exception {
        boolean negative = false;
        int intLen = 0;
        int fractLen = 0;
        int expLen = 0;

        JsonToken token = parser.callResetFloat(negative, intLen, fractLen, expLen);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, token);
        assertEquals(0, getInternalField("_intLength"));
        assertEquals(0, getInternalField("_fractLength"));
        assertEquals(0, getInternalField("_expLength"));
    }

    /**
     * Helper method to access protected fields of ParserBase via reflection.
     */
    private Object getInternalField(String fieldName) throws Exception {
        Field field = ParserBase.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(parser);
    }
}
